/* Generated by tools/gen_roof_pickup.py: original pickup switch. */
static void roof_library_key_pickup(ShTown *town, ShSavegame *save, const ShInputState *input, float dt)
{
    if (!town->step) {
        town->pickup_item_id = 69;
        town->pickup_scale = town->pickup_spin = 0;
        town->pickup_msg = s_school_roof_messages[44].text;
    }

    switch (town->step)
    {
        case 0:
            (town->controls_locked = true);
            (town->pickup_active = true);
            step_set(town, town->step + 1);
        /* fall through */

        case 1:
            step_set(town, town->step + 1);
            break;

        case 2:
            card_animation(town, 59, dt);
            break;

        case 3:
            step_set(town, town->step + 1);
            break;

        case 4:
            
            upper_pickup_prompt(town, save, &s_school_roof_key_pickup, input, dt, &town->step);
            if (town->step == 6)
            {
                sh_save_event_clear(save, 108);
            }
            break;

        case 5:
            sh_save_item_add(save, 69, 1);
            step_set(town, town->step + 1);
        /* fall through */

        case 6:
            town->pickup_active = town->prompt_open = false;
            town->subtitle = NULL;
            card_animation(town, 60, dt);
            break;

        default:
            
            ladder_unfreeze(town);
            finish(town);
            break;
    }
}
